/**
 * bonus game
 */
cc.Class({
    extends: cc.Component,

    properties: {
        _slotsUI:null,

        _col:20,     //列
        _row:1,     //行
        _reels:[],   //卷轴脚本对象
        _cfg:null,
        _stopTime:null, //停止时间
        _exitLast: null,
        _exitCallBack: null,

        _bStopRightnow:null, //立即停止

        _restNum:0, //剩余次数
        _curNum:0,  //当前次数

        _emptyId:18, // 空格图标id
        _greenId:4,  // 绿底图标id
        _wildId:2,   // wild图标id
    },

    Init(){
        this._slotsUI = cc.find("safe_node/slots/respin_slots", this.node);
        this._topAnimationNode = cc.find("top_ani", this._slotsUI);
        this._top_ani = cc.find("top_ani",this._slotsUI);           //--------------
        this._particle_sj = cc.find("particle_sj",this._slotsUI);
        this._particle_sj.active = false;

        this._node_spine = cc.find("safe_node/slots/node_respin", this.node);
        this._node_spine.active = false;
        this._spine_jsk = cc.find("spine_jishukuang", this._node_spine);
        this._node_allNum = cc.find("node_allNum",this._spine_jsk);
        this._spine_winner= cc.find("spine_winner",this._spine_jsk);
        this._node_allNum.active = false;
        this._spine_winner.active = false;
        this._node_times = cc.find("node_times",this._node_spine);

        this._bonusBg = cc.find("safe_node/spr_bg_respin", this.node);

        this.createReels(this._col)
        this.initAllHolderState(false);
    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    //创建卷轴
    createReels:function(col){
        for (let i = 0; i < col; i++) {
            let node = cc.find("reels/reel" + (i+1),this._slotsUI)
            let scp = node.addComponent("TheGodOfFortune_BonusReel")
            scp.Init(i,1,this._top_ani)
            this._reels.push(scp)
        }
    },

    // 初始化所有背景图
    initAllBg(bShow){
        for (let col = 0; col < this._col; col++){
            this._reels[col].showBonusBg(bShow);
        }
    },

    // 初始化所有wild停留框状态
    initAllWildKuang(bShow){
        for (let col = 0; col < this._col; col++){
            this._reels[col].showBonusWildKuang(bShow);
        }
    },

    // 设置单个wild停留框状态 idx(1->20)
    setWildKuangByIdx(idx, bShow){
        this._reels[this.getColByIdx(idx)].showBonusWildKuang(bShow);
    },

    // 初始化所有小单格状态
    initAllHolderState(bShow){
        for(let col = 0; col < this._col; col++){
            this._reels[col].showBonusHolder(bShow);
        }
    },

    // 设置单个小单格状态 idx(1->20)
    setHolderStateByIdx(idx, bShow){
        this._reels[this.getColByIdx(idx)].showBonusHolder(bShow);
    },

    getHolderByIdx(idx){
        return this._reels[this.getColByIdx(idx)].getBonusHolder();
    },

    // 初始化所有小单格状态
    initAllBonusSymbol(){
        for(let col = 0; col < this._col; col++) {
            this._reels[col].showBonusHolder(false);
            this._reels[col].GetSymbolByRow(0).ShowById(this._emptyId);
        }
    },

    // 显示十局中最后一局的转动
    async playLastGame(exitCallBack){
        cc.vv.gameData.setIsEndOfRound(true);

        let idxs = cc.vv.gameData.getNormalWildIdxs();
        for (let i = 0; i < idxs.length; i++){
            this._reels[this.getColByIdx(idxs[i])].showBonusBg(true);
            let sym = this.GetSymbolByIdx(idxs[i]);
            sym.playBonusRedKuangAnim(true);
        }
        await this.awaitTime(2);

        this.StartMove();

        await this.awaitTime(0.5);
        let lastList = cc.vv.gameData.getLastGame();
        let reelsData = this.creatReelData(lastList.info);
        this.SetSlotsResult(reelsData);
        cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_2");

        this._exitLast = exitCallBack;
    },

    // 进入bonus小游戏
    async enterBonusGame(data,exitCallBack, isFrist){

        Global.SlotsSoundMgr.stopBgm();
        Global.SlotsSoundMgr.playBgm("ngbgm");

        cc.vv.gameData.setIsBonusGame(true);
        cc.vv.gameData.GetCollectScript().setBtnCollectState(false);

        this._exitCallBack = exitCallBack;
        this._bonusBg.active = true
        this._slotsUI.active = true;

        this.initData(data);
        this.initPool(true);
        if (isFrist) {
            cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1");

            await this.awaitTime(1);

            await cc.vv.gameData.GetPopupScript().showStartBonus();
        }else {
            cc.vv.gameData.setIsEndOfRound(false)
        }
        await this.awaitTime(2);

        this.sendNextRound();
    },

    // 退出小游戏
    exitBonusGame(){
        cc.vv.gameData.setIsEndOfRound(false)
        cc.vv.gameData.setIsBonusGame(false);
        cc.vv.gameData.GetCollectScript().setBtnCollectState(true);

        this._bonusBg.active = false;
        this._node_spine.active = false;
        this._spine_winner.active = false;

        this.initAllWildKuang(false)
        this.initAllBg(false);
        this.initAllHolderState(false)
        this.initAllBonusSymbol()

        this.initPool(false);
    },


    initData(data){
        this._node_spine.active = true;

        let list = data.info;
        let newList = {};   // 只保留金币和奖池的节点
        for(let key in list){
            if (list[key].type === "coin" || list[key].type === "pool"){
                newList[key] = list[key];
            }else if (list[key].type === "wild"){
            }
        }
        this.initAllWildKuang(false);

        let reelsData = this.creatReelData(newList);
        this.SetSlotsResult(reelsData);

        let count = 0;
        for (let i = 0; i < 20; i++){
            let symbol = this.GetSymbolByIdx(i+1);
            symbol.ShowById(reelsData[i].sid, reelsData[i].data)

            symbol.node.parent.active = true;

            this._reels[this.getColByIdx(i+1)].showBonusBg(true);

            if (reelsData[i].sid !== 18){

                let symScp = this.ShowSymbolTopAni(0,this.getColByIdx(i+1))
                symScp.showBonusWildKuang(true);

                count += 1;
            }
        }

        this._restNum = data.num ? data.num : 3;
        this._curNum = this._restNum;
        this.updateSpinsNum(false);

        this.updateAllPrizeNum(count)
    },

    //
    initPool(bShow){
        let prizepool = cc.find('Canvas/safe_node/LMSlots_PrizePool_1').getComponent("LMSlots_PrizePool_Base");

        if (bShow){
            let poolList = cc.vv.gameData.getBonusPoolList();
            prizepool.PausePool([{prizeType:0,pauseNum:poolList[0]},{prizeType:1,pauseNum:poolList[1]},
                {prizeType:2,pauseNum:poolList[2]},{prizeType:3,pauseNum:poolList[3]}]);
        }else {
            prizepool.ResumePausePool();
        }
    },

    // 触发时的绿色加速框动画
    playGreenTriAnim(){
        let list = cc.vv.gameData.getLastGame().info;
        let colList = [];   // 只保留金币和奖池的节点
        for(let key in list){
            if (list[key].type === "coin" || list[key].type === "pool"){
                let idx = Number(key.substring("idx_".length));
                colList.push(this.getColByIdx(idx));
            }
        }

        for(let i = 0; i < colList.length; i++){
            this._reels[colList[i]].ShowAntiEffect(true);
        }

    },

    hideAllGreenAnim(){
        for (let col = 0; col < this._col; col++){
            this._reels[col].ShowAntiEffect(false);
        }
    },

    //更新次数
    updateSpinsNum(isLast){

        if (this._restNum > this._curNum){
            Global.SlotsSoundMgr.playEffect("num2");
            let spine_bomb = this._node_times.getChildByName("spine_bomb");
            spine_bomb.active = true;
            spine_bomb.getComponent(sp.Skeleton).setAnimation(0,"animation",false);
            spine_bomb.getComponent(sp.Skeleton).setCompleteListener(()=>{
                spine_bomb.active = false;
            })
        }

        this._curNum = this._restNum;
        let pic = "theme185_respin_wenben1";

        if(!isLast){
            pic = "theme185_respin_wenben"+(4-this._restNum);
        } else{
            pic = "theme185_respin_wenben5";
        }

        this._node_times.active = true
        this._node_times.getChildByName("spr").getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetAtlasByName("base").getSpriteFrame(pic);
    },

    // 更新总数
    updateAllPrizeNum(num){
        if(num > 0){
            let lbl = this._node_allNum.getChildByName("lbl_nums").getComponent(cc.Label);

            if(num > Number(lbl.string)){
                Global.SlotsSoundMgr.playEffect("num1")
                let spine_bomb = this._node_allNum.getChildByName("spine_bomb");
                spine_bomb.active = true;
                spine_bomb.getComponent(sp.Skeleton).setAnimation(0,"animation",false);
                spine_bomb.getComponent(sp.Skeleton).setCompleteListener(()=>{
                    spine_bomb.active = false;
                })
            }

            this._node_allNum.active = true;
            lbl.string = num;
        } else {
            this._node_allNum.active = false;
        }
    },


    //点击旋转按钮调用
    StartMove(){
        this._bStopRightnow = false
        if (cc.vv.gameData.isEndOfRound()){
            let idxs = cc.vv.gameData.getNormalWildIdxs();
            for (let i = 0; i < idxs.length; i++){

                this.setHolderStateByIdx(idxs[i], true);
            }
        } else {
            this._restNum -= 1;
            this.updateSpinsNum(false);
        }

        this.MoveReels(this._reels)
        this._stopTime = this.GetStopTime()
    },

    onMsgSpine(msg){
        this._coinBonusInfo = msg.coinBonus;
        this._totalTime = this._coinBonusInfo.total;

        let info =  this._coinBonusInfo.info;
        let reelsData = this.creatReelData(info);
        this.SetSlotsResult(reelsData);

        this._restNum = this._coinBonusInfo.num;

        cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_2");
    },

    MoveReels(arry){
        this.moveReelLastIdx = -1

        for(let i = 0; i < arry.length; i++){
            let item = arry[i]
            item.StartMove()

            let idx = item.GetReelIdx()
            if (cc.vv.gameData.isEndOfRound()){
                let idxs = cc.vv.gameData.getNormalWildIdxs();
                if(idxs.includes(this.getIdxByCol(idx)) && idx > this.moveReelLastIdx){
                    this.moveReelLastIdx = idx
                }
            } else {
                if(idx> this.moveReelLastIdx){
                    this.moveReelLastIdx = idx
                }
            }
        }
    },


    //点击停止按钮调用
    StopMove:function(){
        this._bStopRightnow = true
        cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1")

        this._stopTime = -1
        for(let i = 0; i < this._reels.length; i++ ){
            let item = this._reels[i]
            let reelStopInterv = 0 //立即停止
            item.StopMove(reelStopInterv)
            item.StopMoveRightNow()
        }

    },

    // 将服务器数据转换成客户端卷轴数据
    creatReelData:function(list){
        let reelData = [];
        for (let index = 0; index < 20; index++) {
            let info = {};
            info.sid = this._emptyId;
            info.data = {};
            reelData.push(info)
        }

        for (let key in list){
            let idx = Number(key.substring("idx_".length));
            reelData[idx-1].sid = this.convertTypeToId(list[key].type);

            reelData[idx-1].data=list[key];
        }

        return reelData
    },

    // 将type转换为id类型
    convertTypeToId(type){
        let id = this._emptyId;
        if (type === "coin" || type === "pool"){
            id = this._greenId;
        } else if (type === "wild"){
            id =this._wildId;
        }
        return id;
    },

    SetSlotsResult:function(reelsData){
        //把结果按卷轴结果整理
        let acRow = reelsData.length / this._col
        let reelResults = []
        for(let i = 0;i < reelsData.length; i++){
            // let row = Math.floor(i / acRow)
            let col = this.getColByIdx(i+1);
            let res = {}
            res.sid = reelsData[i].sid //符号id
            res.data = reelsData[i].data
            if(!reelResults[col]) reelResults[col] = []
            reelResults[col].unshift(res)   
        }
        for(let i = 0; i < this._reels.length; i++){
            let item = this._reels[i]
            let reelRes = reelResults[i]
            item.SetResult(reelRes)
        }
    },


    // 发送下一次旋转请求
    sendNextRound(){
        cc.vv.gameData.GetBottomScript().SendSpinReq();
    },

    //列回弹动作之前
    OnReelBounsActionBefore(colIdx){

        //检查加速
        if (cc.vv.gameData.isEndOfRound()){
            let idxs = cc.vv.gameData.getNormalWildIdxs();
            if(!idxs.includes(this.getIdxByCol(colIdx))){
                return
            }

            let count = 0;
            let bLast = true;
            for(let i = 0; i <= colIdx; i++){
                if(idxs.includes(this.getIdxByCol(i))){
                    if(this._reels[i].GetSymbolByRow(0).GetShowId() === this._greenId){
                        count += 1;

                        for (let s = colIdx+1; s < this._col; s++){
                            if(idxs.indexOf(this.getIdxByCol(s))){
                                bLast = false;
                                break;
                            }
                        }
                    }
                }
            }

            if(count >= 5 && !bLast){
                let includeNum = 0;
                for(let i = colIdx+1; i < this._col; i++){
                    if(idxs.includes(this.getIdxByCol(i))){
                        if(includeNum === 0){
                            this._reels[i].playAntiAnimation();
                        }
                        includeNum += 1;

                        let nAddSpeedTime = cc.vv.gameData.getGameCfg().AddAntiTime || 1
                        this._reels[i].AddDelayTime(nAddSpeedTime)
                    }
                }
            }
        }
    },

    //回弹动作最低点
    OnReelBounsActionDeep(colIdx){
    },

    //列回弹动作完成之后
    OnReelBounsActionEnd(colIdx){

        for (let row = 0; row < this._row; row++){
            let syc = this.getSymbolTopAni(row, colIdx);
            if (syc){
            }else {
                let symScp = this._reels[colIdx].GetSymbolByRow(row);
                if (symScp.GetShowId() === this._wildId){
                    if (cc.vv.gameData.isEndOfRound()){
                        Global.SlotsSoundMgr.playEffect("symbol_wild");
                        symScp.playStopAnimation();
                        this.showKuangLast(colIdx);
                    }
                }

                if(symScp.GetShowId() === 4){
                    if (cc.vv.gameData.isEndOfRound()){
                        Global.SlotsSoundMgr.playEffect("symbol_bonus2");
                        symScp.playStopAnimation();
                        this.showKuangLast(colIdx);
                    }else {
                        this.showStopAni(row, colIdx)

                        if(!this._bStopRightnow){
                            let lbl = this._node_allNum.getChildByName("lbl_nums").getComponent(cc.Label);
                            let num = Number(lbl.string) + 1;
                            this.updateAllPrizeNum(num)
                        }
                    }
                }
            }
        }
    },

    async showKuangLast(col){
        this._reels[col].showBonusWildKuang(false);
        await this.awaitTime(0.5);
        this._reels[col].showBonusWildKuang(true);
    },

    async showStopAni(row, col){
        let symScpTop = this.ShowSymbolTopAni(row, col)
        symScpTop.playStopAnimation();
        await this.awaitTime(0.5)
        symScpTop.showBonusWildKuang(true);
    },

    //全部列都停止了
    //处理停下后的中奖情况，这里多数情况需要根据自己的逻辑来处理
    async OnSpinEnd(){

        if (cc.vv.gameData.isEndOfRound()){
            await this.awaitTime(1)
            cc.vv.gameData.setIsBonusGame(false);

            if (this._exitLast){
                this._exitLast();
            }
        }
        else {
            this.updateAllPrizeNum(this._coinBonusInfo.total);
            if (this._restNum > 0){
                this.updateSpinsNum(false);

                await this.awaitTime(1);
                this.sendNextRound();
            }else {
                this.updateSpinsNum(true);
                Global.SlotsSoundMgr.playEffect("respin_end");

                await this.awaitTime(1);

                await this.playSJAnim();

                let nWin = cc.vv.gameData.GetBottomScript().getCurrentWin();
                let total = nWin;

                await cc.vv.gameData.GetPopupScript().showEndBonus(total);

                // 显示底部赢钱
                await new Promise((sucess, failed)=>{
                    cc.vv.gameData.GetSlotsScript().ShowBottomWin(nWin,total,true,sucess)
                });

                cc.vv.gameData.GetPopupScript().playQP1Anim();
                await this.awaitTime(1.5);
                if(cc.vv.gameData.GetTotalFree() <= 0){
                    cc.vv.gameData.GetSlotsScript().setRandomCards();
                }

                this.exitBonusGame();
                this.hideAllTopAni();

                await this.awaitTime(2);

                Global.SlotsSoundMgr.stopBgm();
                cc.vv.gameData.GetSlotsScript().playGameBgm();
                if (this._exitCallBack){
                    this._exitCallBack();
                }
            }
        }

    },

    hideAllTopAni(){
        for (let col = 0; col < this._col; col++){
            for (let row = 0; row < this._row; row++){
                let symScp = this.getSymbolTopAni(row, col);
                if(symScp){
                    symScp.node.destroy()
                }
            }
        }
    },

    // bonus游戏完成后的收集动画
    async playSJAnim(){
        return new Promise(async (sucess, failed)=> {
            this._node_allNum.active = false;
            this._node_times.active = false;

            this._spine_winner.active = true;
            this._spine_winner.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
            Global.SlotsSoundMgr.playEffect("frame_change");

            let lbl_num = this._spine_winner.getChildByName("lbl_result");
            lbl_num.getComponent(cc.Label).string = "";

            await this.awaitTime(1);

            let num = 0;
            let lbl_bottom = cc.vv.gameData.GetBottomScript().getCurrentWin();
            for (let col=0; col < this._col; col++){
                for (let row = this._row-1; row >= 0; row--){
                    let symScp = this._reels[col].GetSymbolByRow(row);
                    if (symScp.getPrize() > 0 ){
                        symScp.playCollectAnim();

                        let startPos = this._slotsUI.convertToNodeSpaceAR(symScp.node.convertToWorldSpaceAR(cc.v2(0,0)));
                        let endPos = this._slotsUI.convertToNodeSpaceAR(lbl_num.convertToWorldSpaceAR(cc.v2(0,0)));
                        let moveT = 0.3;
                        this.flyParticle(startPos, endPos, moveT);
                        await this.awaitTime(moveT);

                        let prize = symScp.getPrize();
                        Global.doRoallNumEff(lbl_num,num,num+prize, 0.3,null,null,0,true);
                        num = num + prize;

                        cc.vv.gameData.GetBottomScript().SetWin(lbl_bottom+prize);
                        lbl_bottom = lbl_bottom+prize;


                        this._spine_winner.getChildByName("spine_win_zi").active = true;
                        this._spine_winner.getChildByName("spine_win_zi").getComponent(sp.Skeleton).setAnimation(0,"animation",false);

                        await this.awaitTime(0.2);
                    }
                }
            }
            sucess();
        })
    },

    flyParticle(startPos, endPos, moveT){
        Global.SlotsSoundMgr.playEffect("fly1");

        let par = cc.instantiate(this._particle_sj);

        par.active = true;
        par.getComponent(cc.ParticleSystem).resetSystem();
        par.parent = this._slotsUI;
        par.position = startPos;

        par.runAction(cc.sequence(cc.moveTo(moveT, endPos), cc.destroySelf()));
    },

    //显示节点动画到top_ani节点
    //不受框体的限制，不受mask的显示。即显示在slots的最上层
    //nRow:行，从下往上数0开始， nCol:列，从0开始
    //return:该节点的控制脚本，自己获取后，可以控制动画的播放
    ShowSymbolTopAni:function(nRow,nCol){
        let cfg = cc.vv.gameData.getGameCfg()
        let symScp = cfg.scripts.Symbols
        let showNode = cc.find(cc.js.formatStr("top_symbol_%s_%s",nRow,nCol),this._topAnimationNode);
        if(showNode){ //如果已经存在就直接显示
            showNode.active = true
            return showNode.getComponent(symScp)
        }
        else{
            let reel = this._reels[nCol]
            let symbol = reel.GetSymbolByRow(nRow)
            if(symbol){
                let wordPos = symbol.node.convertToWorldSpaceAR(cc.v2(0.0));
                let newNode = cc.instantiate(symbol.node)
                newNode.parent = this._topAnimationNode
                newNode.name = cc.js.formatStr("top_symbol_%s_%s",nRow,nCol)
                newNode.position = this._topAnimationNode.convertToNodeSpaceAR(wordPos)
                return newNode.getComponent(symScp)
            }
        } 
    },

    getSymbolTopAni:function(nRow,nCol){
        let cfg = cc.vv.gameData.getGameCfg()
        let symScp = cfg.scripts.Symbols
        let showNode = cc.find(cc.js.formatStr("top_symbol_%s_%s",nRow,nCol),this._topAnimationNode);
        if(showNode){
            showNode.active = true
            return showNode.getComponent(symScp)
        }
        return null
    },

    //自动停止时间
    //不配的话，就3s后停止
    GetStopTime:function(){
        return cc.vv.gameData.getGameCfg().auto_stop_time || 3
    },

    //设置旋转停止时间
    //如果需要列不停止，可以将时间设置的很大。
    SetStopTime:function(nVal){
        this._stopTime = nVal
    },

    //每列停止时间间隔
    //reelIdx:0开始
    GetReelStopInter:function(reelIdx){
        let nIter = cc.vv.gameData.getGameCfg().bonusReelStopInter || 0.1
        let time = 0

        if(cc.vv.gameData.isEndOfRound()){
            let idxs = cc.vv.gameData.getNormalWildIdxs();

            if (idxs.includes(this.getIdxByCol(reelIdx))){
                let count = 0;
                for (let i = 0; i <= reelIdx; i++){
                    if(idxs.includes(this.getIdxByCol(i))){
                        count += 1;
                    }
                }
                time = count*nIter
                // cc.log(reelIdx,   time);
            }else {
                time = 0;
            }
        } else {
            time = Math.floor(reelIdx/4) * nIter
        }

        return time
    },

    getColByIdx(idx){
        let colList = [1,5,9,13,17, 2,6,10,14,18, 3,7,11,15,19, 4,8,12,16,20];

        return colList[idx-1]-1;
    },

    getIdxByCol(col){
        let idxList = [1,6,11,16, 2,7,12,17, 3,8,13,18, 4,9,14,19, 5,10,15,20];

        return idxList[col];
    },

    //根据服务端序号获取本地的symbol
    GetSymbolByIdx:function(idx){
        let col = this.getColByIdx(idx)
        return this._reels[col].GetSymbolByRow(0)
    },

    //获取最后一个停下来的列序号
    GetLastStopReelIdx:function(){
        return this.moveReelLastIdx
    },

    update (dt) {
        if(this._stopTime > 0){
            this._stopTime = this._stopTime - dt
            if(this._stopTime <= 0){
                for(let i = 0; i < this._reels.length; i++ ){
                    let item = this._reels[i]
                    let reelStopInterv = this.GetReelStopInter(i)
                    item.StopMove(reelStopInterv)
                }
            }
        }

    },

});
