
cc.Class({
    extends: cc.Component,

    properties: {
        _boxes:[],      //箱子列表
        _listofIngots:[],   //每页箱子价格

        _curMapId:0,    // 当前页面id
        _islock:false,

        _isMultLast:1,  // 上一把的倍率 1 2 3
        _multIdx:0, //倍率所在的箱子

        _nextIngot:0,   //开下一个箱子需要的钱

        _isLeftOrRight:0,   // 0：直接打开  1：左  -1: 右
    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    Init(){
        this._btn_collect = cc.find("safe_node/slots/btn_collect", this.node);
        this._btn_collect.on("click", this.onClickCollectBtn.bind(this));
        this.totalbetUpdated();

        this._node_store = cc.find("safe_node/node_store", this.node);
        this._node_store.active = false;

        this._store_bg = cc.find("store_bg", this._node_store);
        this._store_layout = cc.find("layout", this._node_store);

        let btn_close = cc.find("btn_close", this._store_layout);
        btn_close.on("click", this.onClickCloseBtn.bind(this));

        //左移
        let btn_left = cc.find("btn_left", this._store_layout);
        btn_left.on("click", this.onClickLeftBtn.bind(this));
        //右移
        let btn_right = cc.find("btn_right", this._store_layout);
        btn_right.on("click", this.onClickRightBtn.bind(this));

        //箱子
        for (let i=1; i<=9; i++) {
            let box = cc.find("node_box/item"+i, this._store_layout);
            box.on("click", this.onClickBoxBtn.bind(this));
            this._boxes[i] = {
                node: box,
                state:"locking",
                spine_red: box.getChildByName("spine_red"),
                spine_blue: box.getChildByName("spine_blue"),
                moneybg: box.getChildByName("money_bg"),
                lblcoin: cc.find("lbl_wincoin", box).getComponent(cc.Label),
                sprWin: cc.find("spr_win", box).getComponent(cc.Sprite),
                lblprice: cc.find("money_bg/lbl_money", box).getComponent(cc.Label),
                spine_suo: box.getChildByName("spine_suo"),
            };
        }

        this._boxMask = cc.find("node_box/mask",this._store_layout);
        this._boxMask.active = false;

        this._spr_suo = cc.find("node_box/spr_suo",this._store_layout);
        this._spr_suo.active = false;

        this._particle_mult = cc.find("particle_mult", this._store_layout);
        this._particle_mult.active = false;

        this._listofIngots = cc.vv.gameData.getListofIngots();
        this.refreshIngotNum();

        this._btn_tip = cc.find("btn_tip", this._store_layout);
        this._btn_tip.on("click", this.onClickTipBtn.bind(this));
        this._spr_tip = cc.find("spr_tip", this._store_layout);
        this._spr_tip.active = false;

        this._spine_qz = cc.find("store_qz", this._store_layout);
        this._spine_qz.active = false;

        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.onRecvMsgSubAction, this);
    },


    onDestroy(){
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.onRecvMsgSubAction, false, this);
    },

    async onRecvMsgSubAction(msg){
        if (msg.code === 200) {
            if (msg.data.rtype === 2) {  //购买宝箱
                this._nextIngot = msg.data.ingot;
                this.showBuyBox(msg.data);
            } else if (msg.data.rtype === 3) {  //选择页码

                this._pageInfo =  msg.data
                this._boxInfo = msg.data.info ? msg.data.info : [];
                this._nextIngot = msg.data.ingot;

                if(this._isLeftOrRight === 0){
                    this.showStore();
                } else {
                    this.refreshDataWithAction(this._isLeftOrRight * 20);
                    await this.awaitTime(0.15)
                }

                this.refreshData();
            }
        }
    },


    setBtnCollectState(bShow){
        this._btn_collect.active = bShow;
    },

    totalbetUpdated() {
        let islock = cc.vv.gameData.GetBetIdx() < cc.vv.gameData.getUnlockIdx();
        if (islock!=this._islock) {
            this._islock = islock;
            if (islock) {
                this._btn_collect.getChildByName("spine_lock").getComponent(sp.Skeleton).setAnimation(0, "animation1", false);
                Global.SlotsSoundMgr.playEffect("store_lock")
            } else {
                this._btn_collect.getChildByName("spine_lock").getComponent(sp.Skeleton).setAnimation(0, "animation3", false);
                Global.SlotsSoundMgr.playEffect("store_unlock")
            }
        }
    },

    showStore(){
        cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1");
        Global.SlotsSoundMgr.playEffect("dialog_store_show");
        this._node_store.active = true;

        this._store_layout.setScale(0.1);
        cc.tween(this._store_layout)
            .to(0.7, {scale:1})
            .start()

        this._store_bg.opacity = 0;
        cc.tween(this._store_bg)
            .to(0.7,{opacity:255})
            .start()
    },

    async hideStore(){
        cc.vv.gameData.GetBottomScript().ShowBtnsByState("idle");
        // Global.SlotsSoundMgr.playEffect("dialog_store_unlock");

        cc.tween(this._store_layout)
            .to(0.7, {scale:0.1})
            .start()

        cc.tween(this._store_bg)
            .to(0.7,{opacity:0})
            .start()

        await this.awaitTime(0.7)
        this._node_store.active = false;
    },

    refreshData() {
        let data = cc.vv.gameData;
        let atlas_shop = cc.vv.gameData.GetAtlasByName("shop");
        let atlas_base = cc.vv.gameData.GetAtlasByName("base");
        let mapId = cc.vv.gameData.getMapId();

        cc.find("jz_bg/spr_bg", this._store_layout).getComponent(cc.Sprite).spriteFrame = atlas_shop.getSpriteFrame("theme185_store_juan_0"+this._curMapId);
        cc.find("jz_bg/node_lock", this._store_layout).active = this._curMapId > mapId;
        cc.find("jz_bg/node_unlock", this._store_layout).active = this._curMapId <= mapId ;

        cc.find("character_bg/spr_reel", this._store_layout).getComponent(cc.Sprite).spriteFrame = atlas_base.getSpriteFrame("theme185_store_reel_"+this._curMapId);
        cc.find("box_bg", this._store_layout).getComponent(cc.Sprite).spriteFrame = atlas_shop.getSpriteFrame("theme185_store_yuan_0"+this._curMapId);

        //page indicator
        for (let i=1; i<=9; i++) {
            cc.find("choose_bg/choose"+i+"/choosed", this._store_layout).active = (i==this._curMapId);
        }

        //箱子
        for (let i=1; i<=9; i++) {
            // let box_data = this._boxInfo[i-1];
            let box = this._boxes[i];
            let nowPrice = this._listofIngots[this._curMapId-1];

            if (this._boxInfo.length <= 0){ // 未开启

                box.lblcoin.node.active = "";
                box.sprWin.node.active = false;
                box.moneybg.active = true;
                box.lblprice.string = nowPrice;

                this.setBoxAnim(box, "blue", "locking");
                this.setBoxLockAnim(box, "locking");

            } else{
                let box_data = this._boxInfo[i-1];
                if (!box_data.lock){  // 已经开启
                    box.lblcoin.node.active = box_data.type === "coin";
                    box.sprWin.node.active = box_data.type !== "coin";
                    box.moneybg.active = false;

                    if (box_data.type === "coin"){
                        box.lblcoin.string = Global.convertNumToShort(box_data.num,1000,0,null,1000);
                    } else if (box_data.type === "free"){
                        box.sprWin.spriteFrame =  atlas_shop.getSpriteFrame("theme185_store_bao_free");
                    } else if (box_data.type === "mult"){
                        box.sprWin.spriteFrame =  atlas_shop.getSpriteFrame("theme185_store_bao_"+box_data.num+"x");
                    }

                    let boxType = box_data.red ? "red" : "blue";

                    this.setBoxAnim(box, boxType, "hasopen");
                    this.setBoxLockAnim(box, "null");
                } else {
                    box.lblcoin.node.active = false;
                    box.sprWin.node.active = false;
                    box.lblprice.string = nowPrice;

                    if(this._pageInfo.ingot  > 0){
                        box.moneybg.active = true;
                        if (cc.vv.gameData.getIngot() < nowPrice) { // 钱不够
                            this.setBoxAnim(box, "blue", "locking");
                            this.setBoxLockAnim(box, "playlock");
                        }else {
                            this.setBoxAnim(box, "blue", "waiting");
                            this.setBoxLockAnim(box, "null");
                        }
                    }
                    else {
                        box.moneybg.active = false;
                        this.setBoxAnim(box, "red", "waiting");
                        this.setBoxLockAnim(box, "null");
                    }

                }
            }
        }

        //元宝数
        this.refreshIngotNum();
    },

    async refreshDataWithAction(deltaX) {

        let node_box = cc.find("node_box", this._store_layout);
        node_box.stopAllActions();
        node_box.x = 0;
        node_box.runAction(cc.sequence(cc.spawn(cc.fadeTo(0.15,63),cc.moveBy(0.15,deltaX,0)),
            cc.spawn(cc.fadeTo(0.15,255),cc.moveBy(0.15,-deltaX,0))));

        await this.awaitTime(0.15);

        for(let i=1; i<=9; i++){
            let box = this._boxes[i].node;
            box.setScale(0.1);

            box.stopAllActions();
            box.runAction(cc.scaleTo(0.1*i, 1,1).easing(cc.easeBackOut()))
        }
    },

    // 箱子打开动画--奖励冒出--（上局为红色）粒子动画，奖励翻倍，其他没打开箱子变蓝 --（这局为红色）--其他箱子变红
    async showBuyBox(data){
        let idx = data.idx;
        let type = data.type;
        let nextIngot = data.ingot;
        let num = data.num;
        let superFree = data.superFree;

        let box = this._boxes[idx];
        box.moneybg.active = false;

        let atlas_shop = cc.vv.gameData.GetAtlasByName("shop");

        // this.refreshIngotNum();

        // 箱子打开
        Global.SlotsSoundMgr.playEffect(this._isMultLast > 1?"chest2":"chest1");
        this.setBoxAnim(box, this._isMultLast > 1?"red":"blue", "opening");
        await this.awaitTime(0.8);
        box.state = "hasopen";

        // 奖励冒出
        let popT = 0.6;
        if (type === "coin"){
            box.lblcoin.node.active = true;

            box.lblcoin.string = Global.convertNumToShort(num/this._isMultLast,1000,0,null,1000);
            await this.playShowPrizeAnim(box.lblcoin.node, popT);

            if(this._isMultLast > 1){
                await this.awaitTime(0.2);
                await this.playMultParAni(idx);
                box.lblcoin.string = Global.convertNumToShort(num,1000,0,null,1000);

                this.recoverBlue(idx)
            }

            cc.vv.gameData.AddCoin(num);
            this.showBottomWin(num,0);

            this._isMultLast = 1;
        } else if(type === "free"){    // 赢得免费
            box.sprWin.node.active = true;
            box.sprWin.spriteFrame =  atlas_shop.getSpriteFrame("theme185_store_bao_free");
            await this.playShowPrizeAnim(box.sprWin.node, popT);

            if(this._isMultLast > 1) {
                await this.awaitTime(0.2);
                await this.playMultParAni(idx);
                this.recoverBlue(idx)
            }

            // cc.vv.gameData.setFreeType("click");
            cc.vv.gameData.setFreeType(cc.vv.gameData.getFreeTypeList().click)
            cc.vv.gameData.setFreeMult(this._isMultLast);

            this.hideStore();
            await this.awaitTime(0.8);
            cc.vv.gameData.GetSlotsScript().CheckEnterFreeGame();
            this._isMultLast = 1;
        } else if (type === "mult"){  // 倍率
            box.sprWin.node.active = true;
            box.sprWin.spriteFrame =  atlas_shop.getSpriteFrame("theme185_store_bao_"+num+"x");
            await this.playShowPrizeAnim(box.sprWin.node, popT);

            this._isMultLast = num;
            this._multIdx = idx;

            // 剩下箱子变红色
            for (let i = 1; i <= 9; i++){
                let box_i = this._boxes[i];
                if (box_i.state === "locking" || box_i.state === "waiting"){
                    this.setBoxAnim(box_i, "red", "waiting");
                }
            }
        }

        // 钱不够开下一个箱子
        if(cc.vv.gameData.getIngot() < this._nextIngot){
            for (let i = 1; i <= 9; i++){
                let box_i = this._boxes[i];
                if (box_i.state === "locking" || box_i.state === "waiting"){
                    this.setBoxAnim(box_i, "blue", "locking");
                    this.setBoxLockAnim(box_i, "playlock");
                }
            }
        }


        this._boxMask.active = false;
        if (superFree){
            await this.awaitTime(1);
            // cc.vv.gameData.setFreeType("super");

            Global.SlotsSoundMgr.playEffect("super_trigger");
            this._spine_qz.active = true;
            this._spine_qz.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
            this._spine_qz.getComponent(sp.Skeleton).setCompleteListener(()=>{
                this._spine_qz.active = false;
            })

            await this.awaitTime(1);
            cc.vv.gameData.setFreeType(cc.vv.gameData.getFreeTypeList().super)
            cc.vv.gameData.setFreeMult();
            cc.vv.gameData.GetSlotsScript().CheckEnterFreeGame();

            this.hideStore();
        }
    },

    // 冒出奖励动画
    playShowPrizeAnim(node, moveT){
        return new Promise((sucess, failed)=> {
            if (node) {
                node.setScale(0);
                node.runAction(cc.sequence(cc.scaleTo(moveT, 1).easing(cc.easeBackOut()), cc.callFunc(()=>{sucess()})));
            }else {
                sucess();
            }
        })
    },

    // 倍率粒子动画
    playMultParAni(endIdx){
        return new Promise((sucess, failed)=>{
            let startPos = this._store_layout.convertToNodeSpaceAR(this._boxes[this._multIdx].node.convertToWorldSpaceAR(cc.v2(0,0)))
            let endPos = this._store_layout.convertToNodeSpaceAR(this._boxes[endIdx].node.convertToWorldSpaceAR(cc.v2(0,0)))

            this._particle_mult.active = true;
            this._particle_mult.getComponent(cc.ParticleSystem).resetSystem();
            this._particle_mult.position = startPos;
            Global.SlotsSoundMgr.playEffect("fly3");
            cc.tween(this._particle_mult)
                .to(0.3, {position:endPos})
                .call(()=>{
                    this._particle_mult.active = false;
                    sucess()
                })
                .start()
        })
    },

    // 箱子恢复原来颜色
    recoverBlue(idx){
        for (let i = 1; i <= 9; i++){
            let box_i = this._boxes[i];
            if (i !== idx){
                this.setBoxAnim(box_i, "blue", box_i.state);
            }
        }
    },

    // 显示底部赢钱
    showBottomWin(end,begin,rollTime){
        return new Promise((sucess, failed)=>{
            cc.vv.gameData.GetTopScript().ShowCoin();
            cc.vv.gameData.GetBottomScript().ShowWin(end,null,begin,function () {
                sucess()
            },rollTime);
        })
    },

    // 刷新余额
    refreshIngotNum(){
        let str = Global.FormatNumToComma(cc.vv.gameData.getIngot());
        cc.find("lbl_money", this._btn_collect).getComponent(cc.Label).string = str;
        cc.find("layout/money_bg/lbl_money", this._node_store).getComponent(cc.Label).string = str;
    },

    onClickCollectBtn(){
        if (!cc.vv.gameData.GetBottomScript().GetSpinBtnState()) return;
        if (cc.vv.gameData.isFreeGame()) return;
        if (cc.vv.gameData.GetAutoModelTime() > 0) return;

        if (!cc.vv.gameData.GetBottomScript().GetSpinBtnState()) return;
        if (!this._islock) {
            this._curMapId = cc.vv.gameData.getMapId();

            let req = {c: MsgId.SLOT_SUBGAME_DATA};
            req.gameid = cc.vv.gameData.getGameId();
            req.data = {
                rtype: 3,
                mapId:this._curMapId,
            };
            cc.vv.NetManager.send(req,true);

            this._isLeftOrRight = 0;
        }
        else {
            let minIdx = cc.vv.gameData.getUnlockIdx();
            let allMults = cc.vv.gameData.GetBetMults();
            if(minIdx > allMults.length){
            }else {
                cc.vv.gameData.GetBottomScript().SetBetIdx(minIdx)
            }
        }
    },

    onClickCloseBtn(){
        Global.SlotsSoundMgr.playEffect("btn_click")
        this.hideStore();
    },

    onClickLeftBtn(){
        Global.SlotsSoundMgr.playEffect("page")

        this._curMapId = this._curMapId > 1 ? this._curMapId - 1 : 9;

        let req = {c: MsgId.SLOT_SUBGAME_DATA};
        req.gameid = cc.vv.gameData.getGameId();
        req.data = {
            rtype: 3,
            mapId:this._curMapId,
        };
        cc.vv.NetManager.send(req,true);

        this._isLeftOrRight = 1;
    },

    onClickRightBtn(){
        Global.SlotsSoundMgr.playEffect("page")

        this._curMapId = this._curMapId < 9 ? this._curMapId + 1 : 1;

        let req = {c: MsgId.SLOT_SUBGAME_DATA};
        req.gameid = cc.vv.gameData.getGameId();
        req.data = {
            rtype: 3,
            mapId:this._curMapId,
        };
        cc.vv.NetManager.send(req,true);


        this._isLeftOrRight = -1;
    },

    onClickBoxBtn(event) {

        for (let i=1; i<=9; i++) {
            if (event.node == this._boxes[i].node) {
                let restIngot = cc.vv.gameData.getIngot() - this._nextIngot;
                if ( restIngot < 0){
                    this.playSprSuoAnim(event.node)
                    this._boxes[i].spine_suo.getComponent(sp.Skeleton).setAnimation(0,"animation2",false);

                    return
                }

                if (this._boxes[i].state === "waiting"){
                    this._boxMask.active = true;

                    let req = {c: MsgId.SLOT_SUBGAME_DATA};
                    req.gameid = cc.vv.gameData.getGameId();
                    req.data = {
                        rtype: 2,
                        mapId:cc.vv.gameData.getMapId(),
                        idx:i,
                    };
                    cc.vv.NetManager.send(req,true);

                    cc.vv.gameData.setIngot(restIngot);
                    this.refreshIngotNum();
                }
            }
        }
    },

    setBoxAnim(box,type, state){
        box.spine_red.active = type === "red";
        box.spine_blue.active = type === "blue";
        let ske = (type === "red")? box.spine_red.getComponent(sp.Skeleton) : box.spine_blue.getComponent(sp.Skeleton);

        if (state === "locking"){ // 锁
            ske.setAnimation(0, "animation1", true);
            this.setBoxMask(ske.node, true);
        } else if (state === "waiting"){ // 等待打开
            ske.setAnimation(0, "animation2", true);
            this.setBoxMask(ske.node, false);
        } else if (state === "opening"){ // 打开
            ske.setAnimation(0, "animation3", false);
            ske.addAnimation(0, "animation4", true);
            this.setBoxMask(ske.node, false);
        } else if (state === "hasopen"){ // 已经打开
            ske.setAnimation(0, "animation4", true);
            this.setBoxMask(ske.node, false);
        }

        box.state = state;
    },

    setBoxMask(node, isMask){
        if(isMask){
            node.color = new cc.Color(100, 100, 100);
        }else {
            node.color = cc.Color.WHITE;
        }
    },

    setBoxLockAnim(box, state){
        if (state === "null"){
            box.spine_suo.active = false;
        } else {
            box.spine_suo.active = true;

            let ske = box.spine_suo.getComponent(sp.Skeleton);
            if (state === "locking") {
                ske.setAnimation(0, "animation1", true);
            } else if(state === "playlock"){
                ske.setAnimation(0, "animation3", false);
                ske.addAnimation(0, "animation1", true);
            }
        }
    },

    exitClickFree(){
        this.showStore();
    },

    // 退出SuperFree
    async exitSuperFree(){
        this.showStore();

        await this.awaitTime(1.7);

        if(this._curMapId === 10){
            cc.vv.gameData.GetPopupScript().showUnlockAllMap();
            cc.vv.gameData.setMapId(1);
        } else {
            cc.vv.gameData.GetPopupScript().showUnlockMap();
            cc.vv.gameData.setMapId(this._curMapId + 1);
        }

    },


    onClickTipBtn(){
        Global.SlotsSoundMgr.playEffect("btn_click");
        this._spr_tip.stopAllActions();
        if(this._spr_tip.active){
            this._spr_tip.runAction(cc.sequence(
                cc.scaleTo(this._spr_tip.scaleX/2,0,0),
                cc.callFunc(()=>{ this._spr_tip.active = false;})
            ))
        } else {
            this._spr_tip.active = true;
            this._spr_tip.setScale(0);
            this._spr_tip.runAction(cc.sequence(
                cc.scaleTo(0.5,1,1),
                cc.callFunc(()=>{ this._spr_tip.active = true;}),
                cc.delayTime(1),
                cc.scaleTo(0.5,0,0),
                cc.callFunc(()=>{ this._spr_tip.active = false;})
            ))
        }
    },

    playSprSuoAnim(box){
        Global.SlotsSoundMgr.playEffect("tip");
        this._spr_suo.stopAllActions();
        if(this._spr_suo.active){
            this._spr_suo.runAction(cc.sequence(
                cc.scaleTo(this._spr_suo.scaleX/2,0,0),
                cc.callFunc(()=>{ this._spr_suo.active = false;})
            ))
        } else {
            this._spr_suo.position = box.position;
            this._spr_suo.active = true;
            this._spr_suo.setScale(0);
            this._spr_suo.runAction(cc.sequence(
                cc.scaleTo(0.5,1,1),
                cc.callFunc(()=>{ this._spr_suo.active = true;}),
                cc.delayTime(1),
                cc.scaleTo(0.5,0,0),
                cc.callFunc(()=>{ this._spr_suo.active = false;})
            ))
        }
    },


    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    // update (dt) {},
});
