

cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {

        _curTimes:0,    //当前展示局数

        _superWildList:[],  // 超级免费对应的wild节点
    },

    Init(top,bottom){

        this._game_times = cc.find("node_game_times", this.node);
        this._node_mult = cc.find("node_mult",this.node);
        this._node_mult.active = false;
        this._node_super_wild = cc.find("node_super_wild",this.node);
        this._node_super_wild.active = false;
        for(let i = 0; i < this._node_super_wild.childrenCount; i++){
            let item = this._node_super_wild.getChildByName("item"+(i+1));
            item.active = false;
            this._superWildList.push(item);
        }

        this._super(top,bottom);
    },

    RegisterEvent:function(){
        this._super();

        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED,this.onEventTotalbetUpdated,this)// 押注额改变
    },

    async ReconnectShow(){
        let idxs = [];
        // 免费游戏
        if (cc.vv.gameData.GetTotalFree() > 0){
            // 普通免费
            // 点击免费
            // 超级免费
            this.ShowGameview(true);
            this._free_times = 10 - cc.vv.gameData.GetFreeTime();
            this._curTimes = this._free_times;
            this.updateTimes(this._curTimes);// 当前局数

            if(cc.vv.gameData.GetFreeTime() > 0){
                let freeType = cc.vv.gameData.getFreeType();
                if(freeType === cc.vv.gameData.getFreeTypeList().super){
                    this.showSuperWildNode(true);
                    cc.vv.gameData.GetCollectScript().setBtnCollectState(false);
                }

                idxs = cc.vv.gameData.getFreeGameData().wealthGod.idxs;
                this.showBonusWildKuang(idxs);// 当前wild框
            }

        }else {
            this.ShowGameview(false);
            this.showCurBetState();
        }

        let select = cc.vv.gameData.getSelectInfo();
        if(select && select.state && select.rtype){
            if (select.rtype === 1){// bonus游戏
                await new Promise(async (sucess, failed) => {
                    this._curTimes = 0;
                    this.updateTimes();
                    cc.vv.gameData.GetBonusScript().enterBonusGame(cc.vv.gameData.getCoinBonus(), sucess, true);
                })
            }
        }

        // bonus小游戏中
        if (cc.vv.gameData.getCoinBonus() && cc.vv.gameData.getCoinBonus().num > 0) {
            await new Promise(async (sucess, failed) => {
                this._curTimes = 0;
                this.updateTimes();
                cc.vv.gameData.GetBonusScript().enterBonusGame(cc.vv.gameData.getCoinBonus(), sucess, false);
            })
        }

        if(cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetFreeTime() == 0){
            await this.CheckExitFreeGame();
        }

        this._topScript.StopMove()
        this._bottomScript.CanDoNextRound();
    },

    onEventTotalbetUpdated() {
        cc.vv.gameData.GetCollectScript().totalbetUpdated();

        this.showCurBetState();
    },

    StartMove(){
        if(cc.vv.gameData.isBonusGame()){
            let slots = cc.vv.gameData.GetBonusScript();
            slots.StartMove();
            return
        }

        if(cc.vv.gameData.isEndOfRound()){
            cc.vv.gameData.GetBonusScript().exitBonusGame();
        }

        this._super();

        this._curTimes += 1;
        this.updateTimes(this._curTimes);

        let freeType = cc.vv.gameData.getFreeType();
        if (freeType === cc.vv.gameData.getFreeTypeList().super){
            this.showSuperWildNode(true)
        }else {
            this.showSuperWildNode(false)
        }

        Global.SlotsSoundMgr.playNormalBgm()
    },

    StopMove(){
        if(cc.vv.gameData.isEndOfRound() || cc.vv.gameData.isBonusGame()){
            let slots = cc.vv.gameData.GetBonusScript()
            slots.StopMove()
        } else {
            this._super()
        }
    },

    onMsgSpine(msg){
        this._gameInfo = msg;
        let cards = msg.resultCards;
        cards = this.changeLionId(cards);// 狮子图标
        cards = this.changeWildSuper(cards);    // 超级免费时wild图标
        this.SetSlotsResult(cards);
        this.SetReelStateInfo(cards)
    },

    //处理结果给reel设置结果
    SetSlotsResult:function(cards){
        //把结果按卷轴结果整理
        let acRow = cards.length / this._col
        let reelResults = []
        for(let i = 0;i < cards.length; i++){
            let row = Math.floor(i / acRow)
            let col = i % this._col
            //配置中有没有这个元素
            if(this._cfg.symbol[cards[i]]){
                let res = {}
                res.sid = cards[i] //符号id

                let num = this.getIngotNum(i+1);
                if(num > 0){
                    res.data ={type:"ingot", num:num};
                }

                if(!reelResults[col]) reelResults[col] = []
                reelResults[col].unshift(res)
            }
        }

        for(let i = 0; i < this._reels.length; i++){
            let item = this._reels[i]
            let reelRes = reelResults[i]
            item.SetResult(reelRes)
        }
    },

    //列回弹动作最低点
    OnReelBounsActionDeep(colIdx){
        for (let row = 0; row < this._row; row++){
            if (this._reels[colIdx].GetSymbolByRow(row).GetShowId() === 1){
                this._reels[colIdx].GetSymbolByRow(row).playStopAnimation();
                Global.SlotsSoundMgr.playEffect("symbol_bonus1");
            }
        }
    },

    //全部列都停止了
    OnSpinEnd:function(){
        this.showSuperWildNode(false)
        this.onSpinEndAction();
    },

    async onSpinEndAction(){
        if (this._gameInfo.allFreeCnt === 0 || this._gameInfo.allFreeCnt === this._gameInfo.freeCnt){
            // 每局转完，将财神奖金数据存起来
            let betIdx = cc.vv.gameData.GetBetIdx();
            cc.vv.gameData.setWealthGodByIdx(betIdx-1, this._gameInfo.wealthGod)
        }

        // 元宝收集
        if (this._gameInfo.collect && this._gameInfo.collect.info){
            this.playIngotFlyAnim(this._gameInfo.collect);
        }

        let idxs = cc.vv.gameData.getNormalWildIdxs();
        // 显示wild停留框
        this.showBonusWildKuang(idxs);

        // 最后一局
        if (cc.vv.gameData.getNormalNum() === 0){
            await this.playLastGame();
        }

        // 显示中奖路线
        this.ShowWinTrace()
        // 显示底部赢钱
        let nWin = cc.vv.gameData.GetGameWin()
        let nTotal = nWin
        if(cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()){
            nTotal = cc.vv.gameData.GetGameTotalFreeWin()
        }
        await new Promise((sucess, failed)=>{
            this.ShowBottomWin(nWin,nTotal,true,sucess)
        });

        // 触发免费
        let freeInfo = this._gameInfo.freeResult.freeInfo;
        if (freeInfo && freeInfo.freeCnt > 0){
            cc.vv.gameData.setFreeType(cc.vv.gameData.getFreeTypeList().normal)
            cc.vv.gameData.setFreeMult();
            await this.CheckEnterFreeGame();
        }

        // 触发bonus游戏
        let triBonus = false;
        let lastData = cc.vv.gameData.getLastGame();
        if (lastData && lastData.info && lastData.isTriBonus){
            triBonus = true;
            if(lastData.poolList){
                cc.vv.gameData.setBonusPoolList(lastData.poolList);
            }
            await this.CheckEnterBonusGame();
        }

        if(this._gameInfo.allFreeCnt > 0 && this._gameInfo.freeCnt == 0){
            if (triBonus){
                await this.awaitTime(2.5);
            }
            await this.CheckExitFreeGame();
        }

        this.CanDoNextRound();
    },

    setRandomCards(){
        for (let col = 0; col < this._col; col++){
            for (let row = 0; row < this._row; row++){
                let sym = this._reels[col].GetSymbolByRow(row);

                sym.setAnimationToTop(false)
                sym.ShowKuang(false)
                sym.stopWinTweenAction()
                sym.node.zIndex = 50 - this._symbolIdx  + this._reelIdx*10;
                sym.ShowRandomSymbol();
            }
        }
    },

    // 修改狮子图标id
    changeLionId(cards){
        for(let col = 0; col < this._col; col++) {
            let isLionList = [0,0,0,0];
            let lionCnt = 0;
            for (let row = 0; row < this._row; row++){
                let id = this.GetResutByRowCol(cards, row, col);
                if (id === 6){
                    isLionList[row] = 1;
                    lionCnt += 1;
                }
            }

            if (lionCnt > 0){
                if(isLionList[0] > 0){
                    for (let i = 0; i < lionCnt; i++){
                        isLionList[i] = lionCnt-i;
                    }
                } else {
                    for (let i = 3; i >= (4-lionCnt); i--){
                        isLionList[i] = (5 - lionCnt) + (3-i);
                    }
                }

                for (let row = 0; row < this._row; row++){
                    let col1 = this.ChangeRowColToIdx(cards,row,col);
                    if (isLionList[row] === 1){
                        cards[col1] = 601
                    } else if (isLionList[row] === 2){
                        cards[col1] = 602
                    } else if (isLionList[row] === 3){
                        cards[col1] = 603
                    } else if (isLionList[row] === 4){
                        cards[col1] = 604
                    }
                }
            }
        }

        return cards;
    },

    //显示中奖路线
    //竞品中的显示线路是：先总，后单条循环。目前我们只显示总的
    ShowWinTrace:function(){
        let allWinIdx = []

        //中奖位置
        for(let i = 0; i < this._gameInfo.zjLuXian.length; i++){
            let item = this._gameInfo.zjLuXian[i]
            for(let idx = 0; idx < item.indexs.length; idx++){
                allWinIdx[item.indexs[idx]] = 1
            }
        }
        if(this._gameInfo.scatterZJLuXian && this._gameInfo.scatterZJLuXian.indexs){
            for(let i = 0; i < this._gameInfo.scatterZJLuXian.indexs.length; i++){
                let val = this._gameInfo.scatterZJLuXian.indexs[i]
                allWinIdx[val] = 1
            }
        }

        //总
        for (const key in allWinIdx) {
            let symbol = this.GetSymbolByIdx(Number(key))
            if(symbol){
                let id = symbol.GetShowId();
                let holder = cc.vv.gameData.GetBonusScript().getHolderByIdx(Number(key));
                if (holder.active){
                    let playSym = cc.vv.gameData.GetBonusScript().GetSymbolByIdx(Number(key));
                    playSym.playBonusWinAnim();
                } else if(id === 601 || id === 602 || id === 603){
                    let col = (Number(key) - 1) % this._col;
                    let row = this._row - Math.floor((Number(key) -1)/this._col) -1
                    let playRow = id + row > 604 ? id + row - 604 : 0;
                    let playSym = this._reels[col].GetSymbolByRow(playRow);
                    playSym.playWinAnimation()
                } else {
                    symbol.playWinAnimation()
                }
                symbol.ShowKuang()
            }
        }
    },

    // super free时的wild图标
    changeWildSuper(cards){
        let freeType = cc.vv.gameData.getFreeType();
        if (freeType === cc.vv.gameData.getFreeTypeList().super){
            for (let i = 0; i < cards.length; i++){
                if(cards[i] === 2){
                    cards[i] = 202
                }
            }
        }
        return cards;
    },

    // 获取收集元宝个数
    getIngotNum(idx){
        let num = 0;
        if (this._gameInfo.collect && this._gameInfo.collect.info){
            let info = this._gameInfo.collect.info;
            for( let key in info){
                let key_idx = Number(key.substring("idx_".length));
                if (idx === key_idx){
                    num = info[key];
                    break;
                }
            }
        }

        return num;
    },

    // 元宝收集动画
    playIngotFlyAnim(collect){
        return new Promise(async(sucess, failed)=>{
            let info = collect.info;
            for( let key in info) {
                let idx = Number(key.substring("idx_".length));
                let symbol = this.GetSymbolByIdx(idx);
                if (symbol) {
                    this.showIngotFly(info[key], symbol.getIngotWPos());
                    symbol.showIngot(0);
                }
            }

            await this.awaitTime(0.7);
            cc.vv.gameData.setIngot(collect.num);
            cc.vv.gameData.GetCollectScript().refreshIngotNum();

            sucess();
        });
    },

    // 单个元宝收集动画
    showIngotFly(num, fromWp) {
        if (!this._ingot) {
            this._ingot = cc.instantiate(this.node.getChildByName("ingot"));
        }
        if (!this._ingotEndPos) {
            let icon = cc.find("btn_collect/spr_bg2", this.node);
            this._ingotEndPos = this.node.convertToNodeSpaceAR(icon.convertToWorldSpaceAR(cc.v2(0,0)));
        }
        let ingot = cc.instantiate(this._ingot);
        ingot.active = true;
        let animName = "animation"+num+"_1";
        ingot.getComponent(sp.Skeleton).setAnimation(0, animName, false);
        let pos = this.node.convertToNodeSpaceAR(fromWp);
        ingot.position = pos;
        ingot.parent = this.node;
        ingot.runAction(cc.sequence(cc.moveTo(0.7, this._ingotEndPos), cc.destroySelf()));
        Global.SlotsSoundMgr.playEffect("store_collect");
    },

    // 更新次数
    updateTimes(times){
        if(times >= 0){
            this._game_times.active = true;
            let str = Number(this._game_times.getChildByName("lbl_new").getComponent(cc.Label).string);
            if (str < times){
                Global.SlotsSoundMgr.playEffect("num_change");
                this._game_times.getChildByName("baolizi").active = true;
                this._game_times.getChildByName("baolizi").getComponent(sp.Skeleton).setAnimation(0, "animation", false);
            }
            this._game_times.getChildByName("lbl_new").getComponent(cc.Label).string = times;
        }
        else {
            this._game_times.active = false;
        }
    },

    // 检查获得免费
    async CheckEnterFreeGame(){
        return new Promise(async (sucess, failed)=>{

            // 普通旋转中播放触发动画
            if(cc.vv.gameData.getFreeType() === cc.vv.gameData.getFreeTypeList().normal){
                if (this._gameInfo.freeResult && this._gameInfo.freeResult.freeInfo && this._gameInfo.freeResult.freeInfo.freeCnt > 0){
                    for (let id of this._gameInfo.freeResult.freeInfo.idxs) {
                        let symbol = this.GetSymbolByIdx(id)
                        if(symbol){
                            symbol.playTriggerAnimation()
                        }
                    }
                    Global.SlotsSoundMgr.playEffect("bell");
                    await this.awaitTime(1.5);

                    this.Backup();
                }
            }

            // cc.vv.gameData.setIsFreeGame(true);
            await cc.vv.gameData.GetPopupScript().showStartFree();
            cc.vv.gameData.GetPopupScript().playQP2Anim();
            await this.awaitTime(1.8);

            cc.vv.gameData.GetBonusScript().initAllWildKuang(false);
            if(cc.vv.gameData.getFreeType() === cc.vv.gameData.getFreeTypeList().super){
                this.showSuperWildNode(true);
                cc.vv.gameData.GetCollectScript().setBtnCollectState(false);
            }else { // 显示默认wild停留框
                this.refreshWildKuang(true);
            }

            this.ShowGameview(true);
            this._curTimes = 0;
            this.updateTimes(this._curTimes);
            await this.awaitTime(2);
            // Global.playRisingMedusaMusic(this._cfg.soundCfg.free_bgm)

            if(cc.vv.gameData.getFreeType() !== cc.vv.gameData.getFreeTypeList().normal){

                this.CanDoNextRound();
            }

            this.playGameBgm();
            await this.awaitTime(1);
            sucess();
        });
    },

    // 检查退出免费
    async CheckExitFreeGame(){
        return new Promise(async (sucess, failed)=>{
            // cc.vv.gameData.setIsFreeGame(false);
            await cc.vv.gameData.GetPopupScript().showEndFree(cc.vv.gameData.GetGameTotalFreeWin());
            cc.vv.gameData.GetPopupScript().playQP2Anim();
            await this.awaitTime(1.8);

            cc.vv.gameData.GetBonusScript().exitBonusGame();

            if(cc.vv.gameData.getFreeType() === cc.vv.gameData.getFreeTypeList().normal){
                this.Resume();
            } else {
                this.setRandomCards();
            }

            this.ShowGameview(false)
            cc.vv.gameData.GetCollectScript().setBtnCollectState(true);
            this.refreshWildKuang(false);
            await this.awaitTime(2);

            Global.SlotsSoundMgr.stopBgm();
            this.playGameBgm();
            sucess();

            // 如果super free
            if(cc.vv.gameData.getFreeType() === cc.vv.gameData.getFreeTypeList().click){
                cc.vv.gameData.GetCollectScript().exitClickFree();
            }else if(cc.vv.gameData.getFreeType() === cc.vv.gameData.getFreeTypeList().super){
                cc.vv.gameData.GetCollectScript().exitSuperFree();
            }

            cc.vv.gameData.setFreeType(cc.vv.gameData.getFreeTypeList().none)
        });
    },

    // 检查触发bonus小游戏
    async CheckEnterBonusGame(){
        return new Promise(async (sucess, failed)=> {
            // 所有节点特效
            Global.SlotsSoundMgr.playEffect("respin_trigger");

            cc.vv.gameData.GetBonusScript().playGreenTriAnim();

            await this.awaitTime(1);
            await cc.vv.gameData.GetPopupScript().playBonusTransition();

            cc.vv.gameData.GetPopupScript().playQP1Anim();
            await this.awaitTime(1.5);
            this.initAllSymbol();
            cc.vv.gameData.GetBonusScript().exitBonusGame();

            let data = cc.vv.gameData.getLastGame();
            cc.vv.gameData.GetBonusScript().hideAllGreenAnim(false);
            await cc.vv.gameData.GetBonusScript().enterBonusGame(data,sucess, true)
        });
    },

    initAllSymbol(){
        for (let col = 0; col < this._col; col++){
            for (let row = 0; row < this._row; row++){
                let sym = this._reels[col].GetSymbolByRow(row);
                sym.setAnimationToTop(false);
                sym.ShowKuang(false);
            }
        }
    },

    // 显示wild停留框
    showBonusWildKuang(idxs){
        cc.vv.gameData.GetBonusScript().initAllWildKuang(false);
        for (let i = 0; i < idxs.length; i++){
            cc.vv.gameData.GetBonusScript().setWildKuangByIdx(idxs[i], true);
        }
    },

    // 刷新wild停留框（针对免费和普通游戏的切换）
    refreshWildKuang(isToFree){
        if(isToFree){
            this._curTimes = 0;
            let idxs = this._cfg.triFreeWildKuang;
            this.updateTimes(this._curTimes);// 当前局数
            this.showBonusWildKuang(idxs);// 当前wild框

        } else {
            this.showCurBetState()
        }
    },

    // 显示当前押注的wild停留框和当前局数
    showCurBetState(){
        if(cc.vv.gameData.isFreeGame()){
            return
        }
        let idxs = []
        let curIdx = cc.vv.gameData.GetBetIdx()
        let allWealthGod = cc.vv.gameData.getAllwealthGod();
        if(allWealthGod[curIdx-1]){
            this._curTimes = 10- allWealthGod[curIdx-1].num;
            this._curTimes = this._curTimes===10?0:this._curTimes;
            idxs = allWealthGod[curIdx-1].idxs;
        } else {
            this._curTimes = 0;
            idxs = [];
        }

        this.updateTimes(this._curTimes);// 当前局数
        this.showBonusWildKuang(idxs);// 当前wild框
    },

    //播放最后一局bonus
    async playLastGame(){
        return new Promise(async (sucess, failed)=> {
            this._curTimes = 0;
            this.updateTimes();
            // this._game_times.active = false;
            Global.SlotsSoundMgr.playEffect("kuanglizi");
            cc.vv.gameData.GetBonusScript().playLastGame(sucess);
        })
    },

    // 设置免费倍率标题
    setFreeMultTitle(){
        let freeMult = cc.vv.gameData.getFreeMult();

        this._node_mult.active = freeMult === 2 || freeMult === 3;
        if(this._node_mult.active){
            this._node_mult.getChildByName("spr_mult2").active = freeMult === 2;
            this._node_mult.getChildByName("spr_mult3").active = freeMult === 3;
        }
    },

    // 显示super free wild停留的节点
    showSuperWildNode(bShow){
        this._node_super_wild.active = bShow;

        if(bShow){
            let mapId = cc.vv.gameData.getMapId()
            let list = this._cfg.superFreeWildKuang[mapId-1];

            for(let i = 0; i < list.length; i++){
                this._superWildList[i].active = list[i]
            }
        } else {
            for (let i = 0; i < this._superWildList.length; i++){
                this._superWildList[i].active = false;
            }
        }
    },

    //显示游戏界面：bFree true显示免费模式的界面，false 普通模式
    ShowGameview:function(bFree){
        if(bFree){
            let total = cc.vv.gameData.GetTotalFree()
            let rest = cc.vv.gameData.GetFreeTime()

            if(!total){
                total = 10;
                cc.vv.gameData.SetTotalFree(total)
            }
            if(!rest){
                rest = 10
                cc.vv.gameData.SetFreeTime(rest)
            }

            //显示免费次数
            this._bottomScript.ShowFreeModel(true,total-rest,total)
            let nTotal = cc.vv.gameData.GetTotalFreeWin()
            this._bottomScript.SetWin(nTotal)

            this.setFreeMultTitle();
        }
        else{
            this._bottomScript.ShowFreeModel(false)
            this._node_mult.active = false;
        }

        cc.vv.gameData.setIsFreeGame(bFree);

        //可能还需要显示免费背景图
        let normalBg = cc.find("Canvas/safe_node/spr_bg_normal");
        let normalFree = cc.find("Canvas/safe_node/spr_bg_free");
        if(normalFree){ //存在免费游戏背景才执行下面的逻辑
            if(normalBg){
                normalBg.active = !bFree
            }
            normalFree.active = bFree
        }

        // 人物动画
        // let spine_character = cc.find("Canvas/safe_node/spine_character");
        // let animName = bFree ? "animation2" : "animation1";
        // spine_character.getComponent(sp.Skeleton).setAnimation(0, animName, true);
    },

    // 播放游戏背景音乐
    playGameBgm(){
        if (cc.vv.gameData.isFreeGame()){ //免费

            let freeType = cc.vv.gameData.getFreeType();
            if(freeType === cc.vv.gameData.getFreeTypeList().super){
                Global.SlotsSoundMgr.playBgm("fgbgm");
            }else {
                Global.SlotsSoundMgr.playBgm("fgbm");
            }
        } else {
            Global.SlotsSoundMgr.playNormalBgm();
        }

    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },
});
