/**
 * -符号表
 */
cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {
        _ingot:null,

        _bonusIndex:0,

        _type:"",   // normal-""  1-"bonus_1" 2-"bonus_2"
    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    ingot() {
        if (!this._ingot) {
            this._ingot = this.node.getChildByName("ingot");
        }
        return this._ingot;
    },

    start () {

    },

    StartMove(){
        this._super();

        this.hideOther();

    },

    hideOther(){
        this.showIngot();
        this.setNum();
        this.setPool();
        this.setPrize();
        this.showBonusWildKuang(false);
    },

    //显示symbole
    ShowById:function(id,data){
        this._super(id, data);

        this.hideOther();
        if(data){
            if(data.type === "ingot" && data.num){  // 元宝
                this.showIngot(data.num);
            }
            else if(data.type === "coin" && data.num){  // 金币
                this.setNum(data.num);
            }
            else if(data.type === "pool" && data.num){  // 奖池
                this.setPool(data.num);
            }
            else if(data.type === "wild"){  // wild
                // this.hideOther();
            }
        }

    },

    showIngot(num){

        if(this.ingot()){
            if (num > 0){
                this.ingot().active = true;
                this.ingot().getChildByName("spr").getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetAtlasByName("symbol").getSpriteFrame("theme185_s_jiao"+num);
            }else {
                this.ingot().active = false;
            }
        }
    },

    //获取元宝位置
    getIngotWPos(){
        return this.ingot().convertToWorldSpaceAR(cc.v2(0,0));
    },


    // 显示类型
    setType(type){
        this._type = type;
    },

    //显示随机符号
    ShowRandomSymbol:function(){
        let cfg = cc.vv.gameData.getGameCfg();

        let ramSym = [];
        let data = null;
        if(this._type === "bonus_1"){
            ramSym = Global.copy(cfg.bonusRandom1);
        } else if (this._type === "bonus_2"){
            ramSym = Global.copy(cfg.bonusRandom2);
        }
        else {
            ramSym = Global.copy(cfg.randomSymbols);
        }

        let randIdx = Global.random(1,ramSym.length)
        let randVal = ramSym[randIdx-1]

        if(randVal === 4 && (this._type === "bonus_1" || this._type === "bonus_2")){
            let randIdx2 = Global.random(1,cfg.bonusCoinMultList.length)
            let randData = cfg.bonusCoinMultList[randIdx2-1] * cc.vv.gameData.GetTotalBet()
            data = {type : "coin", num: randData}
        }
        this.ShowById(randVal,data)

    },

    setBonusIndex(index){
        this._bonusIndex = index
    },

    getBonusIndex(){
        return this._bonusIndex;
    },

    // bonus
    playBonusRedKuangAnim(bShow){
        if(bShow){
            let aniNode = this.setBonusAnimationToTop(true)
            let topShowNode = cc.find("kuang_red",aniNode)
            topShowNode.active = true;
            aniNode.zIndex = 1000;
            let nodeSp = topShowNode.getComponent(sp.Skeleton)
            if(nodeSp){
                nodeSp.setAnimation(0,"animation", false);
                nodeSp.setCompleteListener(()=>{
                    this.setBonusAnimationToTop(false)
                })
            }
        }else {
            cc.find("kuang_red", this.node).active = false;
        }

    },

    //在顶层播放动画；能覆盖左右两列
    setBonusAnimationToTop(isTop){
        if(this._topAniNode){
            if (isTop) {
                let cloneNode = cc.find(cc.js.formatStr("symbol_ani_%s_%s",this._bonusIndex,this._reelIdx),this._topAniNode);
                if (!cloneNode) {
                    cloneNode = cc.instantiate(this.node)
                }
                let wordPos = this.node.convertToWorldSpaceAR(cc.v2(0.0));
                cloneNode.parent = this._topAniNode
                cloneNode.name = cc.js.formatStr("symbol_ani_%s_%s",this._bonusIndex,this._reelIdx)
                cloneNode.position = this._topAniNode.convertToNodeSpaceAR(wordPos)
                this.node.active = false
                return cloneNode
            }else{
                let showNode = cc.find(cc.js.formatStr("symbol_ani_%s_%s",this._bonusIndex,this._reelIdx),this._topAniNode);
                if (showNode) {
                    showNode.removeFromParent()
                }
                this.node.active = true
                if(this._showNode){
                    this._showNode.active = true
                }
            }
        }
        return this.node
    },

    // 设置价值
    setPrize(val){
        this._prize = val;
    },

    getPrize(){
        return this._prize;
    },

    // 设置金币
    setNum(num){
        let lbl = cc.find("lbl_coin",this.node);
        if (lbl){
            if (num){
                lbl.active = true;
                lbl.getComponent(cc.Label).string = Global.formatNumShort(num);
                this.setPrize(num);
            } else {
                lbl.active = false;
            }
        }
    },

    setPool(num){
        let spr = cc.find("spr_pool",this.node);
        if (spr){
            if (num){
                spr.active = true;
                spr.getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetAtlasByName("symbol").getSpriteFrame("theme185_s_j"+(4-num));
                let pool = cc.vv.gameData.getBonusPoolList();
                this.setPrize(pool[num])
            }else {
                spr.active = false;
            }
        }
    },

    showBonusWildKuang(bShow){
        let spine_kuang = cc.find("kuang_wild", this.node);
        if (spine_kuang){
            if(bShow){
                spine_kuang.active = true;
                spine_kuang.getComponent(sp.Skeleton).setAnimation(0, "animation1", true);
            }
            else {
                spine_kuang.active = false;
            }
        }
    },


    // 收集动画
    playCollectAnim(){
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].collect_ani){
            // this._state = "stop";
            if(this._showNode){
                this._showNode.active = false
            }
            this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
            this._showNode.active = true

            if(cfg.symbol[id].collect_ani.name != ""){
                this.node.zIndex = cfg.symbol[id].collect_ani.zIndex - this._symbolIdx  + this._reelIdx*10;
                let nodeSp = this._showNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].collect_ani.name,false)
                }
            }
        }
    },

    //---------狮子
    // 赢钱动画
    playWinAnimation(){
        let id = this._id;
        if(id === 601 || id === 602 || id === 603 || id === 604){
            this.playLionWinAnim();
        }else {
            this._super()
        }
    },

    // 狮子赢钱动画
    playLionWinAnim(){
        // let win_id = this._symbolIdx+this._id > 604 ? 604: this._symbolIdx+this._id;
        let cfg = cc.vv.gameData.getGameCfg();

        if(cfg.symbol[this._id] && cfg.symbol[this._id].win_node && cfg.symbol[this._id].win_ani){
            this._state = "win";
            if(this._showNode){
                this._showNode.active = false
            }
            this._showNode = cc.find(cfg.symbol[this._id].win_node,this.node);
            this._showNode.active = true;

            if(cfg.symbol[this._id].win_ani.name != ""){

                this._showNode.zIndex = cfg.symbol[this._id].win_ani.zIndex - this._symbolIdx + this._reelIdx*10;
                let nodeSp = this._showNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[this._id].win_ani.name,true)
                }
            }
        }
    },

    // bonus赢钱动画
    playBonusWinAnim(){
        let cfg = cc.vv.gameData.getGameCfg();

        if(cfg.symbol[this._id] && cfg.symbol[this._id].win_node && cfg.symbol[this._id].win_ani){
            if(this._showNode){
                this._showNode.active = false
            }
            this._showNode = cc.find(cfg.symbol[this._id].win_node,this.node);
            this._showNode.active = true;

            if(cfg.symbol[this._id].win_ani.name != ""){

                // this._showNode.zIndex = cfg.symbol[this._id].win_ani.zIndex - this._symbolIdx + this._reelIdx*10;
                let nodeSp = this._showNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[this._id].win_ani.name,true)
                }
            }
        }
    },

    GetKuangShowParent:function(){
        return cc.find("Canvas/safe_node/slots/top_kuang");
    },

    //触发动画
    //触发了才播放的。比如已经3个scatter已经触发了免费。这个和中奖的还不一样
    playTriggerAnimation(){
        let isPlay = false
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].trigger_ani){
            this._state = "trigger";
            if(this._showNode){
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
            topShowNode.active = true
            if(cfg.symbol[id].trigger_ani.name != ""){
                aniNode.zIndex = cfg.symbol[id].trigger_ani.zIndex - this._symbolIdx + this._reelIdx*10;
                isPlay = true
                let nodeSp = topShowNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].trigger_ani.name,true)
                }
            }
        }
        return isPlay
    },

    // update (dt) {},
});
